const fs = require('fs')

const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
const root = '.agents/workflows'
const sources = Object.fromEntries(
  fs.readdirSync(root)
    .filter((file) => file.endsWith('.js'))
    .map((file) => [
      file.replace(/\.js$/, ''),
      fs.readFileSync(`${root}/${file}`, 'utf8').replace(/^export const meta/m, 'const meta'),
    ]),
)

function assert(condition, message) {
  if (!condition) throw new Error(message)
}

function verdict(lens, result = 'PASS', lie = false) {
  return {
    lens,
    verdict: result,
    findings: result === 'PASS'
      ? []
      : [{ summary: 'finding', evidence: 'evidence', fix: lie ? '' : 'fix' }],
    refutationAttempts: ['attempted refutation'],
    proofChecked: ['checked proof'],
  }
}

function runner(responder) {
  const calls = []
  const prompts = []
  const execute = async (name, args) => {
    const source = sources[name]
    if (!source) throw new Error(`unknown workflow ${name}`)
    const workflow = (childName, childArgs) => execute(childName, childArgs)
    const agent = async (prompt, options) => {
      calls.push(options.label)
      prompts.push({ label: options.label, prompt, options })
      const attempt = calls.filter((label) => label === options.label).length
      return responder(options.label, prompt, attempt)
    }
    const parallel = async (tasks) => Promise.all(tasks.map((task) => task()))
    return new AsyncFunction('args', 'workflow', 'agent', 'parallel', 'log', source)(
      args,
      workflow,
      agent,
      parallel,
      () => {},
    )
  }
  return { execute, calls, prompts }
}

async function expectThrow(fn, includes) {
  try {
    await fn()
  } catch (error) {
    assert(String(error.message).includes(includes), `expected error containing ${includes}, got ${error.message}`)
    return
  }
  throw new Error(`expected error containing ${includes}`)
}

